import { describe, it, expect, beforeEach } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { provideZonelessChangeDetection } from '@angular/core';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { WatchItem } from '../app/movie';

function item(id: number, watched: boolean): WatchItem {
  return { id, title: `Movie ${id}`, watched, poster_path: null, release_date: '2024-01-01' };
}

describe('Watchlist ordering', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      providers: [provideZonelessChangeDetection(), WatchlistStore]
    });
  });

  it('shows unwatched movies before watched ones', async () => {
    const store = TestBed.inject(WatchlistStore);
    // seed the store directly through its behaviour
    const watched1 = item(1, true);
    const unwatched2 = item(2, false);
    store.add({ id: 1, title: 'Movie 1', release_date: '2024-01-01', poster_path: null, overview: '' });
    store.add({ id: 2, title: 'Movie 2', release_date: '2024-01-01', poster_path: null, overview: '' });
    store.toggleWatched(1);

    const fixture = TestBed.createComponent(Watchlist);
    await fixture.whenStable();
    const movies = fixture.componentInstance.movies();
    const watchedIds = movies.filter(m => m.watched).map(m => m.id);
    const unwatchedIds = movies.filter(m => !m.watched).map(m => m.id);
    const firstWatchedIndex = movies.findIndex(m => m.watched);
    if (watchedIds.length > 0) {
      expect(firstWatchedIndex).toBe(unwatchedIds.length);
    }
    expect(movies.map(m => m.id)).toEqual([2, 1]);
  });
});

